#include <vector>
#include <algorithm>

// Returns the minimum cost to climb to the top of a staircase.
// cost[i] is the cost to step on stair i. You may start on stair 0 or 1
// without paying. From any stair you can climb 1 or 2 stairs.
int minCostToReachTop(const std::vector<int>& cost) {
    // For zero or one stairs, no payment is needed because you can
    // start on the only stair and step to the top.
    if (cost.size() <= 1) {
        return 0;
    }

    // a = minimum cost to reach position i-2 (top of that stair)
    // b = minimum cost to reach position i-1
    int a = 0;
    int b = 0;

    for (std::size_t i = 1; i < cost.size(); ++i) {
        // Option 1: come from i-2 and pay cost[i-1] (the stair before current)
        // Option 2: come from i-1 and pay cost[i] (the current stair)
        int current = std::min(a + cost[i - 1], b + cost[i]);
        a = b;
        b = current;
    }

    return b;
}
